# Use dd to read the file and extract all 23-character sequences, checking for the pattern
dd if=/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat bs=1 2>/dev/null | \
  od -An -tx1 -v 2>/dev/null | \
  tr -d ' ' | \
  sed 's/../& /g' > /tmp/hex_bytes.txt

# Now convert sequences and check pattern
awk 'BEGIN {
  # Read hex bytes and build ASCII representation
  while ((getline line < "/tmp/hex_bytes.txt") > 0) {
    gsub(/ $/, "", line)
    hex_bytes = line
    # Try every 23-byte window
    split(hex_bytes, bytes, " ")
    for (i = 1; i <= length(bytes) - 22; i++) {
      ascii = ""
      for (j = 0; j < 23; j++) {
        hex = bytes[i + j]
        ascii = ascii sprintf("%c", strtonum("0x" hex))
      }
      # Check if it matches pattern: starts with 8XD, ends with W54
      if (ascii ~ /^8XD/ && ascii ~ /W54$/ && ascii ~ /^[A-Z0-9]+$/) {
        print ascii
      }
    }
  }
}' 2>/dev/null | sort -u

